const tabId = 343605414;

const fullDetails = await browserjs(tabId, () => {
  const propertyTitle = document.querySelector('h1')?.textContent?.trim();
  const address = document.querySelector('h1 + p, [class*="address"]')?.textContent?.trim();
  const startingPrice = Array.from(document.querySelectorAll('*')).find(el => el.children.length === 0 && el.textContent.includes('$920'))?.textContent?.trim();

  // Bills section details
  const billsEl = document.querySelector('#bills, [id*="bill"]');
  const billsText = billsEl ? billsEl.innerText : "";

  // Room types and prices
  const roomCards = Array.from(document.querySelectorAll('[data-testid*="room"], [class*="room-card"], [class*="RoomCard"]')).map(r => r.innerText);

  // Check all text mentioning bills or included
  const allBillsIncluded = Array.from(document.querySelectorAll('*'))
    .filter(el => el.children.length === 0 && (el.textContent.includes('Cleaning') || el.textContent.includes('Wifi') || el.textContent.includes('Bills Inclusive')))
    .map(el => el.textContent.trim());

  return {
    propertyTitle,
    address,
    startingPrice,
    billsText,
    allBillsIncluded: [...new Set(allBillsIncluded)],
    url: window.location.href
  };
});

console.log("Full Property Details:", JSON.stringify(fullDetails, null, 2));

